    ("qpack-cross-stream", "Headers wait for a separate encoder stream", "An HTTP/3 field section requires insert count 12, while the decoder has processed only 10 insertions because encoder-stream bytes were lost. The request's bytes can be present and still blocked; receiving the two required insertions allows decoding if all referenced entries remain valid.", ["required-count", "insert-count", "header-blocking", "encoder-stream", "header-decoding"]),
    ("zero-qpack-blocked", "Acknowledged entries remain useful at zero blocking allowance", "A peer sets SETTINGS_QPACK_BLOCKED_STREAMS to zero. The encoder knows the decoder has received 8 entries and can reference retained absolute index 7; it cannot risk a reference to a newly sent unacknowledged entry with index 8. Literal fields remain an alternative.", ["zero-blocked", "known-count", "safe-reference", "literal-static"]),
    ("replay-sensitive-purchase", "A replayed early mutation executes twice without a barrier", "A resumable client sends an early purchase request whose handler has neither idempotency keys nor duplicate detection. If replayed early traffic is accepted in another connection, the purchase can execute twice; rejecting that early operation before processing and requesting a non-early retry avoids that early-execution path.", ["zero-rtt", "early-replay", "repeated-effect", "early-policy", "retry-after-handshake"]),
    ("nat-port-change", "A new observed port still needs reachability handling", "A NAT changes a client's public UDP port while QUIC packets still use a live destination CID. The server can locate connection state and validate the newly observed address using PATH_CHALLENGE/PATH_RESPONSE; RFC 9000 permits retaining congestion and RTT estimates for a port-only change.", ["nat-rebinding", "connection-id", "path-challenge", "path-validation", "path-reset"]),
    ("amplification-cap", "A small client flight limits the server reply", "Before validating a client address, a QUIC server has received 1200 bytes of uniquely attributed UDP payload and sent 3000 bytes. The three-times limit leaves 600 bytes for additional UDP payload; a 900-byte reply must wait for more incoming bytes or address validation, even if congestion credit is available.", ["amplification-budget", "amplification-block", "path-validation", "congestion-window"]),
    ("udp-fallback", "Blocked UDP does not prove the origin is down", "An h3 Alt-Svc endpoint is advertised but the client's path blocks its UDP traffic. QUIC setup fails; if the origin's TCP service remains reachable, a supported HTTP/2 or HTTP/1.1 fallback can still deliver the request's response.", ["alt-svc", "udp-block", "fallback", "http-response"]),
